-- v88. Run after SQL012. Verified directory and resource XP (level cap 10,000).
begin;
create table if not exists tzg_private.resource_progress(user_id uuid primary key references auth.users(id) on delete cascade,xp bigint not null default 0 check(xp>=0 and xp<=4999500000));
alter table tzg_private.resource_progress enable row level security;
revoke all on tzg_private.resource_progress from public,anon,authenticated;
create or replace function tzg_private.account_progress(who uuid) returns jsonb language sql security definer set search_path='' as $$
 with visits as(select count(*)::bigint*100 xp,coalesce(jsonb_agg(body order by visited_at),'[]'::jsonb) worlds from tzg_private.exploration_visits where user_id=who),points as(select least(4999500000,visits.xp+coalesce((select xp from tzg_private.resource_progress where user_id=who),0)) xp,worlds from visits),lev as(select *,least(10000,greatest(1,floor((1+sqrt(1+8*xp/100.0))/2)::integer)) level from points)
 select jsonb_build_object('xp',xp,'level',level,'level_xp',case when level=10000 then 0 else xp-50::bigint*level*(level-1) end,'required_xp',case when level<10000 then 100*level else null end,'worlds',worlds) from lev
$$;
revoke all on function tzg_private.account_progress(uuid) from public,anon,authenticated;
-- Keep the existing save validator, session check, revision lock and mutation idempotency.
do $$begin if to_regprocedure('tzg_private.player_save_before_v88(uuid,bigint,uuid,jsonb)') is null then alter function public.tzg_player_save(uuid,bigint,uuid,jsonb) set schema tzg_private;alter function tzg_private.tzg_player_save(uuid,bigint,uuid,jsonb) rename to player_save_before_v88;end if;end;$$;
revoke all on function tzg_private.player_save_before_v88(uuid,bigint,uuid,jsonb) from public,anon,authenticated;
create or replace function public.tzg_player_save(p_account uuid,p_expected_revision bigint,p_mutation uuid,p_state jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare caller uuid:=tzg_private.require_player();before_row tzg_private.player_saves;result jsonb;spent jsonb:='{}';gained jsonb:='{}';row record;recipe jsonb;ingredient record;count_craft bigint;reward bigint:=0;sold bigint:=0;expected_fp bigint:=0;expected_rc bigint:=0;quantity bigint;rule jsonb;
begin
 if caller is distinct from p_account then raise insufficient_privilege using message='Account changed. Reload before saving.';end if;
 insert into tzg_private.player_saves(user_id) values(caller) on conflict do nothing;
 select * into before_row from tzg_private.player_saves where user_id=caller for update;
 result:=tzg_private.player_save_before_v88(p_account,p_expected_revision,p_mutation,p_state);
 if before_row.last_mutation=p_mutation then return result||jsonb_build_object('progress',tzg_private.account_progress(caller));end if;
 -- Aggregate real accepted inventory deltas. XP cannot be submitted as a client value.
 for row in with old_items as(select value->>'type' type,sum((value->>'qty')::bigint) qty from jsonb_array_elements(before_row.inventory) group by 1),new_items as(select value->>'type' type,sum((value->>'qty')::bigint) qty from jsonb_array_elements(p_state->'inventory') group by 1) select coalesce(o.type,n.type) type,coalesce(o.qty,0)-coalesce(n.qty,0) difference from old_items o full join new_items n on o.type=n.type loop
 if row.difference>0 then spent:=spent||jsonb_build_object(row.type,row.difference);elsif row.difference<0 then gained:=gained||jsonb_build_object(row.type,-row.difference);end if;end loop;
 -- Each recipe consumes the shared input budget once; purchases grant no crafting XP.
 for recipe in select value from jsonb_array_elements('[{"id": "snow-block", "ingredients": {"snow-ball": 12}, "output": 1}, {"id": "log-block", "ingredients": {"tree-log": 1}, "output": 1}, {"id": "wood-planks", "ingredients": {"tree-log": 1}, "output": 4}, {"id": "iron-saw", "ingredients": {"iron": 2, "copper": 1}, "output": 1}, {"id": "steel-saw", "ingredients": {"iron": 4, "tree-log": 3}, "output": 1}, {"id": "diamond-saw", "ingredients": {"diamond": 2, "tree-log": 5}, "output": 1}, {"id": "concrete-white", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-gray", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-charcoal", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-black", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-red", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-orange", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-yellow", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-lime", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-green", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-cyan", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-blue", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-indigo", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-purple", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-pink", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-brown", "ingredients": {"quartz": 1}, "output": 5}, {"id": "concrete-sand", "ingredients": {"quartz": 1}, "output": 5}, {"id": "tnt", "ingredients": {"sulfur": 2, "iron": 1}, "output": 1}, {"id": "door", "ingredients": {"iron": 2, "quartz": 1}, "output": 1}, {"id": "ladder", "ingredients": {"iron": 2}, "output": 1}, {"id": "torch", "ingredients": {"iron": 1, "quartz": 1}, "output": 2}, {"id": "glass", "ingredients": {"quartz": 2}, "output": 5}, {"id": "shovel", "ingredients": {"iron": 2, "quartz": 1}, "output": 1}, {"id": "copper-pickaxe", "ingredients": {"copper": 3, "iron": 1}, "output": 1}, {"id": "steel-pickaxe", "ingredients": {"iron": 5, "cobalt": 2}, "output": 1}, {"id": "diamond-pickaxe", "ingredients": {"diamond": 3, "iron": 5}, "output": 1}]'::jsonb) loop
 count_craft:=coalesce((gained->>(recipe->>'id'))::bigint,0)/(recipe->>'output')::integer;
 for ingredient in select key,value from jsonb_each_text(recipe->'ingredients') loop count_craft:=least(count_craft,coalesce((spent->>ingredient.key)::bigint,0)/ingredient.value::bigint);end loop;
 if count_craft>0 then reward:=reward+25*count_craft;for ingredient in select key,value from jsonb_each_text(recipe->'ingredients') loop spent:=spent||jsonb_build_object(ingredient.key,(spent->>ingredient.key)::bigint-count_craft*ingredient.value::bigint);end loop;end if;
 end loop;
 -- Only remaining saleable resources plus the matching currency increases earn sale XP.
 for rule in select value from jsonb_array_elements('[{"id": "quartz", "fp": 55, "rc": 2}, {"id": "iron", "fp": 70, "rc": 2}, {"id": "copper", "fp": 65, "rc": 2}, {"id": "bauxite", "fp": 80, "rc": 2}, {"id": "gold", "fp": 180, "rc": 2}, {"id": "mica", "fp": 50, "rc": 2}, {"id": "feldspar", "fp": 60, "rc": 2}, {"id": "graphite", "fp": 85, "rc": 2}, {"id": "ilmenite", "fp": 110, "rc": 2}, {"id": "anorthite", "fp": 90, "rc": 2}, {"id": "basalt", "fp": 80, "rc": 2}, {"id": "silica", "fp": 65, "rc": 2}, {"id": "helium", "fp": 220, "rc": 2}, {"id": "hematite", "fp": 110, "rc": 2}, {"id": "olivine", "fp": 100, "rc": 2}, {"id": "gypsum", "fp": 65, "rc": 2}, {"id": "perchlorate", "fp": 85, "rc": 2}, {"id": "sulfur", "fp": 90, "rc": 2}, {"id": "pyrite", "fp": 130, "rc": 2}, {"id": "corundum", "fp": 170, "rc": 2}, {"id": "titanium", "fp": 160, "rc": 2}, {"id": "obsidian", "fp": 140, "rc": 2}, {"id": "ice", "fp": 60, "rc": 2}, {"id": "methane", "fp": 90, "rc": 2}, {"id": "ammonia", "fp": 95, "rc": 2}, {"id": "salt", "fp": 55, "rc": 2}, {"id": "cobalt", "fp": 145, "rc": 2}, {"id": "nickel", "fp": 115, "rc": 2}, {"id": "platinum", "fp": 250, "rc": 2}, {"id": "diamond", "fp": 380, "rc": 2}, {"id": "ruby", "fp": 260, "rc": 2}, {"id": "emerald", "fp": 270, "rc": 2}, {"id": "sapphire", "fp": 275, "rc": 2}, {"id": "lithium", "fp": 135, "rc": 2}, {"id": "chromite", "fp": 155, "rc": 2}, {"id": "magnetite", "fp": 125, "rc": 2}, {"id": "opal", "fp": 190, "rc": 2}, {"id": "garnet", "fp": 185, "rc": 2}, {"id": "zircon", "fp": 210, "rc": 2}, {"id": "tungsten", "fp": 240, "rc": 2}, {"id": "lumenite", "fp": 240, "rc": 2}, {"id": "cryonite", "fp": 260, "rc": 2}, {"id": "starshard", "fp": 350, "rc": 2}, {"id": "voidglass", "fp": 420, "rc": 2}, {"id": "sunstone", "fp": 280, "rc": 2}, {"id": "aetherite", "fp": 380, "rc": 2}, {"id": "prismarine", "fp": 250, "rc": 2}, {"id": "novaore", "fp": 450, "rc": 2}, {"id": "tree-log", "fp": 10, "rc": 1}]'::jsonb) loop quantity:=coalesce((spent->>(rule->>'id'))::bigint,0);sold:=sold+quantity;expected_fp:=expected_fp+quantity*(rule->>'fp')::integer;expected_rc:=expected_rc+quantity*(rule->>'rc')::integer;end loop;
 if sold>0 and (p_state->>'fp')::bigint-before_row.fp>=expected_fp and (p_state->>'rc')::bigint-before_row.rc>=expected_rc then reward:=reward+sold*10;end if;
 if reward>0 then insert into tzg_private.resource_progress(user_id,xp) values(caller,least(4999500000,reward)) on conflict(user_id) do update set xp=least(4999500000,tzg_private.resource_progress.xp+excluded.xp);end if;
 return result||jsonb_build_object('progress',tzg_private.account_progress(caller));end;$$;
revoke all on function public.tzg_player_save(uuid,bigint,uuid,jsonb) from public,anon;
grant execute on function public.tzg_player_save(uuid,bigint,uuid,jsonb) to authenticated;
create or replace function public.tzg_debug_verified_accounts(p_offset integer default 0,p_search text default '') returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;total bigint;query text:=btrim(p_search);begin
 perform public.tzg_debug_authorize(null);
 if p_offset is null or p_offset<0 or p_offset>10000000 or query is null or char_length(query)>100 then raise invalid_parameter_value using message='Invalid account search.';end if;
 select count(*) into total from tzg_private.player_profiles p where (query='' and p.verified) or (query<>'' and (p.username ilike '%'||query||'%' or p.display_name ilike '%'||query||'%'));
 select coalesce(jsonb_agg(to_jsonb(a)),'[]') into result from(select p.user_id,p.username,p.display_name,p.avatar,p.verified from tzg_private.player_profiles p where (query='' and p.verified) or (query<>'' and (p.username ilike '%'||query||'%' or p.display_name ilike '%'||query||'%')) order by p.username,p.user_id limit 25 offset p_offset)a;
 return jsonb_build_object('accounts',result,'total',total);end;$$;
revoke all on function public.tzg_debug_verified_accounts(integer,text) from public,anon;
grant execute on function public.tzg_debug_verified_accounts(integer,text) to authenticated;
-- Keep DM avatar/name verification current in the shared inbox as well as message rows.
do $$begin if to_regprocedure('tzg_private.social_state_before_v88()') is null then alter function public.tzg_social_state() set schema tzg_private;alter function tzg_private.tzg_social_state() rename to social_state_before_v88;end if;end;$$;
revoke all on function tzg_private.social_state_before_v88() from public,anon,authenticated;
create or replace function public.tzg_social_state() returns jsonb language plpgsql security definer set search_path='' as $$
declare caller uuid:=tzg_private.require_player();result jsonb;rooms jsonb;begin
 result:=tzg_private.social_state_before_v88();
 select coalesce(jsonb_agg(r||case when r->>'kind'='dm' then jsonb_build_object('peer',(select tzg_private.social_profile(m.player) from tzg_private.social_members m where m.room=(r->>'id')::uuid and m.player<>caller limit 1)) else '{}'::jsonb end order by ord),'[]') into rooms from jsonb_array_elements(result->'rooms') with ordinality item(r,ord);
 return jsonb_set(result,'{rooms}',rooms);end;$$;
revoke all on function public.tzg_social_state() from public,anon;
grant execute on function public.tzg_social_state() to authenticated;
notify pgrst,'reload schema';
commit;
